@intent_handler("antonym.intent")
def handle_antonym(self, message):
    query = message.data["query"]
    res = self.solver.get_data(query, lang=self.lang).get("antonyms")
    if res:
        self.speak(random.choice(res))
    else:
        self.speak_dialog("no_answer")

